RecursiveUserBadges as (
    select
        u.Id as UserId,
        b.Name as BadgeName,
        b.Class,
        row_number() over (partition by u.Id order by b.Date desc, b.Class desc) as BadgeRank
    from Users u
    left join Badges b on u.Id = b.UserId
    where u.Reputation > 1000
),
FilteredPosts as (
    select 
        p.Id,
        p.PostTypeId,
        coalesce(p.Score,0) as Score,
        p.CreationDate,
        p.OwnerUserId,
        p.AcceptedAnswerId,
        posWeight = ln(nullif(p.ViewCount,0))*10 + p.Score * 3 + coalesce(p.FavoriteCount,0） * 5
    from Posts p
    where p.PostTypeId in (1,2)
      and p.CreationDate >= current_date - interval '365 days'
      and p.Score >= 0
